import decimal
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
PRECISION = 1000


def money_context() -> decimal.Context:
    return decimal.Context(prec=PRECISION, rounding=ROUND_HALF_UP)


def fmt(value: Decimal) -> str:
    with decimal.localcontext(money_context()):
        q = value.quantize(CENT, ROUND_HALF_UP)
        return "0.00" if q == 0 else format(q, "f")

